// Ported 1:1 from LongHorizon-Harness tests/test_role_prompts.py
//
// Every assertion of the Python test module is reproduced below, plus
// golden-snapshot tests whose expected files were generated by running the
// PYTHON originals (see tests/golden/*.txt and tests/golden/parser_cases.json).

import { readFileSync } from "node:fs";
import { test } from "node:test";
import assert from "node:assert/strict";

import {
  AUDITOR_CONTRACT_BACKCHECK,
  TASK_CONTRACT_RULES,
  normalizePromptLanguage,
} from "../src/prompt_texts.js";
import type { PromptLanguage } from "../src/prompt_texts.js";
import {
  MANAGER_NEXT_CLI,
  MANAGER_NEXT_DONE,
  buildRoleAuditorFormatRepairPrompt,
  buildRoleAuditorPrompt,
  buildRoleExecutorPrompt,
  buildRoleFinalResponsePrompt,
  buildRoleManagerPrompt,
  clipPreserve,
  extractRelatedReportRefs,
  extractRoleManagerAnswerChoices,
  extractRoleManagerPlanText,
  extractRoleManagerQuestion,
  extractRoleTaskContract,
  extractRoleTaskState,
  formatAuditFindings,
  formatHarnessFeedbackContext,
  formatManagementHistory,
  formatRelatedAuditorReports,
  formatVerifiedIntermediateContext,
  parseRoleManagerNextStep,
  roundRefToIndex,
} from "../src/role_prompts.js";
import type { ManagedRoundLike } from "../src/role_prompts.js";

const LANGUAGES: PromptLanguage[] = ["en"];

function goldenPath(name: string): URL {
  return new URL(`./golden/${name}`, import.meta.url);
}

function readGolden(name: string): string {
  return readFileSync(goldenPath(name), "utf8");
}

interface GoldenInputs {
  rounds: ManagedRoundLike[];
  manager: {
    task: string;
    round_index: number;
    task_state: string;
    task_contract: string;
    round_budget: number;
    max_history_chars: number;
  };
  executor: {
    task: string;
    plan_text: string;
    next_step: "gui" | "cli";
    task_state: string;
    task_contract: string;
    related_auditor_reports: string;
    workspace_path: string;
  };
  executor_gui: GoldenInputs["executor"];
  auditor: GoldenInputs["executor"] & {
    executor_output: string;
    max_executor_output_chars: number;
  };
  auditor_gui: GoldenInputs["auditor"];
  format_repair: { report_text: string };
  format_repair_empty: { report_text: string };
  final_response: {
    task: string;
    status: string;
    abort_reason: string;
    task_state: string;
    operator_instructions: string;
    max_evidence_chars: number;
    max_deliverable_chars: number;
  };
}

const inputs = JSON.parse(readGolden("inputs.json")) as GoldenInputs;

// ---------------------------------------------------------------------------
// Ported from tests/test_role_prompts.py
// ---------------------------------------------------------------------------

for (const language of LANGUAGES) {
  test(`auditor prompt does not turn unobservable history into a blocker [${language}]`, () => {
    const contractRules = TASK_CONTRACT_RULES[language];
    const auditRules = AUDITOR_CONTRACT_BACKCHECK[language];

    assert.ok(contractRules.includes("does not silently become a historical guarantee"));
    assert.ok(auditRules.includes("missing full executor transcript is not by itself evidence"));
    assert.ok(
      auditRules.includes("unobservable historical negative is non-blocking residual risk"),
    );
    assert.ok(auditRules.includes("Do not request a repeat solely"));
  });

  test(`final response prompt preserves operator follow-up [${language}]`, () => {
    const prompt = buildRoleFinalResponsePrompt({
      task: "Create the requested file.",
      rounds: [],
      status: "complete",
      abortReason: "",
      taskState: "The file was independently verified.",
      operatorInstructions: "The final reply must contain OPERATOR_MARKER.",
      language,
    });

    assert.ok(prompt.includes("OPERATOR_MARKER"));
    assert.ok(prompt.includes("Authoritative operator follow-up instructions"));
  });

  test(`final response prompt includes verified executor deliverable [${language}]`, () => {
    const marker = "https://example.test/source METRIC=405K";
    const prompt = buildRoleFinalResponsePrompt({
      task: "Return the researched report with its citations.",
      rounds: [
        {
          round_index: 1,
          next_step: MANAGER_NEXT_CLI,
          plan_text: "research",
          executor_output: marker,
          auditor_report: "Status: complete\nIntegrity: clean\nContract audit: aligned",
        },
      ],
      status: "complete",
      abortReason: "",
      taskState: "The report was verified.",
      language,
    });

    assert.ok(prompt.includes(marker));
    assert.ok(prompt.includes("preserve every source, citation, figure"));
  });
}

for (const line of [
  "Next: done — all constraints passed",
  "Next: done -- all constraints passed",
]) {
  test(`manager route accepts delimited rationale [${line}]`, () => {
    assert.equal(parseRoleManagerNextStep(line), MANAGER_NEXT_DONE);
  });
}

test("manager route rejects undelimited suffix", () => {
  assert.notEqual(parseRoleManagerNextStep("Next: done later"), MANAGER_NEXT_DONE);
});

for (const language of LANGUAGES) {
  test(`manager prompt exposes total and remaining round budget [${language}]`, () => {
    const prompt = buildRoleManagerPrompt({
      task: "Research and compare the sources.",
      rounds: [],
      roundIndex: 3,
      roundBudget: 10,
      language,
    });

    assert.ok(prompt.includes("Configured round limit: 10"));
    assert.ok(prompt.includes("Rounds remaining, including this one: 8"));
    assert.ok(prompt.includes("do not schedule a prerequisite-only subtask"));
  });
}

test("role prompts distinguish workspace from run records", () => {
  const executor = buildRoleExecutorPrompt({
    task: "create a report",
    planText: "write report.md",
    nextStep: MANAGER_NEXT_CLI,
    workspacePath: "/tmp/workspace",
  });
  const auditor = buildRoleAuditorPrompt({
    task: "create a report",
    planText: "write report.md",
    executorOutput: "done",
    nextStep: MANAGER_NEXT_CLI,
    workspacePath: "/tmp/workspace",
  });

  assert.ok(executor.includes("Workspace root: /tmp/workspace"));
  assert.ok(executor.includes("run-record directory"));
  assert.ok(auditor.includes("Real workspace root: /tmp/workspace"));
  assert.ok(auditor.includes("Executor text is only a claim"));
  assert.ok(auditor.includes("not require every subtask to create a file"));
  assert.ok(auditor.includes("Private Dashboard trajectory images"));
  assert.ok(!auditor.includes(".longhorizon-evidence"));
});

// ---------------------------------------------------------------------------
// Language switch
// ---------------------------------------------------------------------------

test("normalizePromptLanguage mirrors the Python normalizer", () => {
  assert.equal(normalizePromptLanguage("en"), "en");
  assert.equal(normalizePromptLanguage(""), "en");
  assert.equal(normalizePromptLanguage(null), "en");
  assert.equal(normalizePromptLanguage(undefined), "en");
  assert.throws(
    () => normalizePromptLanguage("fr"),
    (error: Error) =>
      error.message === "Unsupported prompt language: 'fr'; expected 'en'.",
  );
});

// ---------------------------------------------------------------------------
// Golden snapshots of the six builders, generated from the Python originals
