// ---------------------------------------------------------------------------
// Golden parser/formatter cases, generated from the Python originals
// ---------------------------------------------------------------------------

interface ParserCase {
  fn: string;
  args: unknown[];
  kwargs: Record<string, unknown>;
  expected: unknown;
}

const parserCases = JSON.parse(readGolden("parser_cases.json")) as ParserCase[];

type Dispatcher = (args: unknown[], kwargs: Record<string, unknown>) => unknown;

const dispatch: Record<string, Dispatcher> = {
  parse_role_manager_next_step: (a) => parseRoleManagerNextStep(a[0] as string),
  extract_role_manager_plan_text: (a) => extractRoleManagerPlanText(a[0] as string),
  extract_role_task_state: (a, k) =>
    extractRoleTaskState(a[0] as string, { fallback: k["fallback"] as string | undefined }),
  extract_role_task_contract: (a, k) =>
    extractRoleTaskContract(a[0] as string, { fallback: k["fallback"] as string | undefined }),
  extract_related_report_refs: (a) => extractRelatedReportRefs(a[0] as string),
  extract_role_manager_question: (a) => extractRoleManagerQuestion(a[0] as string),
  extract_role_manager_answer_choices: (a) => extractRoleManagerAnswerChoices(a[0] as string),
  _round_ref_to_index: (a) => roundRefToIndex(a[0] as string),
  _clip_preserve: (a) => clipPreserve(a[0] as string, a[1] as number),
  format_verified_intermediate_context: (a, k) =>
    formatVerifiedIntermediateContext(a[0] as ManagedRoundLike[], {
      maxChars: k["max_chars"] as number | undefined,
      language: k["language"] as string | undefined,
    }),
  format_related_auditor_reports: (a, k) =>
    formatRelatedAuditorReports(a[0] as ManagedRoundLike[], a[1] as string[], {
      maxChars: k["max_chars"] as number | undefined,
      language: k["language"] as string | undefined,
    }),
  format_harness_feedback_context: (a, k) =>
    formatHarnessFeedbackContext(a[0] as ManagedRoundLike[], {
      maxChars: k["max_chars"] as number | undefined,
    }),
  format_audit_findings: (a, k) =>
    formatAuditFindings(a[0] as ManagedRoundLike[], {
      maxChars: k["max_chars"] as number | undefined,
      language: k["language"] as string | undefined,
    }),
  format_management_history: (a, k) =>
    formatManagementHistory(a[0] as ManagedRoundLike[], {
      includeEmpty: k["include_empty"] as boolean | undefined,
      maxChars: k["max_chars"] as number | undefined,
    }),
};

parserCases.forEach((testCase, index) => {
  test(`golden parser case ${index}: ${testCase.fn}`, () => {
    const handler = dispatch[testCase.fn];
    assert.ok(handler, `no dispatcher for ${testCase.fn}`);
    const args = testCase.args.map((arg) => (arg === "__ROUNDS__" ? inputs.rounds : arg));
    assert.deepEqual(handler(args, testCase.kwargs), testCase.expected);
  });
});
